    private static (IWorkOrderService Order,IInspectionService Inspections) MaintenanceReadOwners(CompanyPPDMRowAccessTests.Fixture f,ModuleConnectionResolver modules,RepositoryUserProfileService profile)
    {
        var gate=f.Gate;IWorkOrderService? orders=null;
        async Task<(CompanyScope Company,string Actor,AssetDatabaseScope Database)> Core(){var access=await gate.RefreshCompanyAsync();var connection=await modules.ResolveAsync("PPDM_CORE");return(access.Scope,access.UserId,new(connection,await modules.GetMigrationBindingFingerprintAsync(["PPDM_CORE"],connection)));}
        var grants=new RepositoryAssetAccessStore(f.Db,gate,Mock.Of<IAssetGrantTargetVerifier>());
        var inspections=new Beep.OilandGas.PPDM39.DataManagement.Services.WorkOrder.InspectionService(f.Editor.Object,f.Columns.Object,f.Defaults.Object,f.Metadata.Object,Core,Microsoft.Extensions.Logging.Abstractions.NullLogger<Beep.OilandGas.PPDM39.DataManagement.Services.WorkOrder.InspectionService>.Instance,async(actor,fieldId,orderId,permission)=>
        {
            gate.RequireActor(actor);await WorkOrderSourceChecks.RequireAsync(fieldId,orderId,async()=>{var preference=(await profile.GetCurrentFieldSelectionAsync()).SelectionContext!;var current=await grants.ReadAsync(actor,preference.Database.Fingerprint);return new[]{("FIELD",fieldId),("WORK_ORDER",orderId)}.All(resource=>current.Any(grant=>grant.UserId==actor && grant.IsActive && grant.OrganizationId==preference.Company.BusinessAssociateId && grant.DatabaseScope==preference.Database.Fingerprint && grant.AssetType==resource.Item1 && grant.AssetId==resource.Item2 && AssetAccessLevelChecks.Meets(grant.AccessLevel,permission)));},()=>orders!.GetByIdAsync(fieldId,orderId),requireState:false);
        },actor=>WorkOrderPermitInspectionAuthority.RequireAsync(gate,f.Http.HttpContext?.User??new ClaimsPrincipal(),actor));
        orders=new Beep.OilandGas.PPDM39.DataManagement.Services.WorkOrder.WorkOrderService(f.Editor.Object,f.Columns.Object,f.Defaults.Object,f.Metadata.Object,inspections,Core,Microsoft.Extensions.Logging.Abstractions.NullLogger<Beep.OilandGas.PPDM39.DataManagement.Services.WorkOrder.WorkOrderService>.Instance,(_,_,_,_)=>throw new InvalidOperationException("No creation command belongs to an inspection read"));return(orders,inspections);
    }
    private static async Task RecordIndependentPrerequisiteInspections(CompanyPPDMRowAccessTests.Fixture f,string order,bool originalPersonnelReference=false,bool originalDocumentReference=false,bool originalRiskReference=false,bool phaseAware=false)
    {
        f.Db.Users.Add(new OilGasUser{Id="prerequisite-inspector",UserName="prerequisite-inspector",IsActive=true,ConcurrencyStamp="prerequisite-inspector-version"});f.Db.UserRoles.Add(new IdentityUserRole<string>{UserId="prerequisite-inspector",RoleId="admin"});await f.Db.SaveChangesAsync();
        f.Request.User=new(new ClaimsIdentity([new("party_id","prerequisite-inspector")],"fixture"));await f.Select("company","prerequisite-inspector");await f.Grant("FIELD","A","WRITE");await f.Grant("WORK_ORDER",order,"WRITE");var profile=Profile(f);await Save(profile);f.Request.User=await new HandoffRoleBridge(f.Gate).TransformAsync(f.Request.User);
        var tenant=new RepositoryTenantContext();tenant.SelectCompany(f.Gate.Company);var modules=new ModuleConnectionResolver(f.Db,f.Editor.Object,tenant);var owners=MaintenanceReadOwners(f,modules,profile);var seq=1;
        foreach(var pair in new[]{("ISOLATION","isolation-document"),("RISK","risk-document"),("PERSONNEL","personnel-document"),("MATERIAL","material-document")})
        {
            var required=await owners.Inspections.AddRequirementAsync(order,new(){FieldId="A",CondSeq=++seq,CondType=ConditionType.PreStart,RequiredText="Explicit "+pair.Item1+" prerequisite",Jurisdiction="Explicit reported jurisdiction",RegulatoryRef=pair.Item2,PermitPrerequisiteKind=pair.Item1,ApplicableStage=phaseAware?"PRE_START":null},"prerequisite-inspector");
            if((pair.Item1=="PERSONNEL" && originalPersonnelReference) || (pair.Item1=="ISOLATION" && originalDocumentReference) || (pair.Item1=="RISK" && originalRiskReference)){Assert.Equal("UNRECORDED",required.Status);continue;}
            InspectionCondition saved;
            if(pair.Item1=="PERSONNEL")
            {
                // Historical generic PASS is an explicit source seam. Current native commands must refuse it.
                var row=f.Rows.OfType<WORK_ORDER_INSPECTION>().Single(value=>value.INSPECTION_ID==required.InspectionId);
                var historical=WorkOrderInspectionRules.PrepareResult(row,new(){FieldId="A",InspectionId=required.InspectionId,ExpectedSourceRevision=required.SourceRevision,Result="PASS",Notes="Historical prerequisite source"},"prerequisite-inspector",DateTime.UtcNow);
                f.Rows.Remove(row);f.Rows.Add(historical);saved=WorkOrderInspectionRules.Project(historical);
            }
            else saved=await owners.Inspections.RecordResultAsync(order,seq,new(){FieldId="A",InspectionId=required.InspectionId,ExpectedSourceRevision=required.SourceRevision,Result="PASS",Notes="Authenticated inspection of original prerequisite reference"},"prerequisite-inspector");Assert.Equal(pair.Item1,saved.PermitPrerequisiteKind);Assert.Equal("PASS",saved.Status);Assert.Equal("prerequisite-inspector",saved.Inspector);
        }
        f.Request.User=new(new ClaimsIdentity([new("party_id","receiver")],"fixture"));f.Http.HttpContext=f.Request;await f.Select("company","receiver");
    }
